// Structure templates of this game (structures.js / jigsaw.js): own designs generated by tools/buildings.py,
// kept as JSON resources (Resources/Data/*.json) and parsed once into these read-only classes.
using System;
using System.Collections.Generic;

namespace Maincraft
{
    /// <summary>A template as stored: size, palette entries, palettes, RLE grid, markers, jigsaws, rules, loot.</summary>
    public sealed class TplSrc
    {
        public int sx, sy, sz;
        public string[] pKey; public int[] pMeta; public int[] pWet;   // S.p
        public int[][] m;                                                // S.m: palettes (state -> entry, 0 nothing)
        public string g;                                                 // base64 RLE grid
        public (int x, int y, int z, string name)[] d = Array.Empty<(int, int, int, string)>();   // markers
        public int[][] j = Array.Empty<int[]>();                         // jigsaws [x, y, z, front, top, name, target, pool, final, rollable]
        public Dictionary<string, Dictionary<string, double[][]>> r = new Dictionary<string, Dictionary<string, double[][]>>();  // processor rules
        public Dictionary<string, double> rRot = new Dictionary<string, double>();   // rules.rot (BlockRotProcessor integrity)
        public (int x, int y, int z, string table)[] l = Array.Empty<(int, int, int, string)>();  // loot
    }

    /// <summary>A pool element: [type 0 single / 1 feature / 2 empty / 3 list, name(s), weight, projection 0 rigid / 1 terrain, processors].</summary>
    public sealed class JigEl
    {
        public int Type;
        public string Name;
        public string[] Names;     // list element
        public int Weight;
        public int Proj;
        public string Proc;
        public string[] Procs;     // list element
    }

    public sealed class JigPool
    {
        public JigEl[] e;
        public string f;           // fallback pool
    }

    public static class StructData
    {
        public static Dictionary<string, TplSrc> STRUCT_TPL;
        public static Dictionary<string, TplSrc> JIG_TPL;
        public static Dictionary<string, JigPool> JIG_POOLS;
        public static string[] JIG_STR;
        public static bool Loaded => STRUCT_TPL != null;

        public static void Load(string structTpl, string jigStr, string jigPools, string jigTpl)
        {
            STRUCT_TPL = ParseTpls(structTpl);
            JIG_TPL = ParseTpls(jigTpl);
            var ls = MiniJson.L(MiniJson.Parse(jigStr));
            JIG_STR = new string[ls.Count];
            for (int i = 0; i < ls.Count; i++) JIG_STR[i] = (string)ls[i];
            JIG_POOLS = new Dictionary<string, JigPool>();
            foreach (var kv in MiniJson.O(MiniJson.Parse(jigPools)))
            {
                var o = MiniJson.O(kv.Value);
                var es = MiniJson.L(o["e"]);
                var pool = new JigPool { e = new JigEl[es.Count], f = MiniJson.S(MiniJson.Get(o, "f")) };
                for (int i = 0; i < es.Count; i++)
                {
                    var a = MiniJson.L(es[i]);
                    var el = new JigEl { Type = MiniJson.I(a[0]), Weight = MiniJson.I(a[2]), Proj = MiniJson.I(a[3]) };
                    if (a[1] is List<object> names) { el.Names = names.ConvertAll(x => (string)x).ToArray(); }
                    else el.Name = (string)a[1];
                    if (a.Count > 4)
                    {
                        if (a[4] is List<object> procs) el.Procs = procs.ConvertAll(x => (string)x).ToArray();
                        else el.Proc = (string)a[4];
                    }
                    pool.e[i] = el;
                }
                JIG_POOLS[kv.Key] = pool;
            }
        }

        static int[] Ints(object o)
        {
            var l = MiniJson.L(o);
            var r = new int[l.Count];
            for (int i = 0; i < r.Length; i++) r[i] = MiniJson.I(l[i]);
            return r;
        }

        static Dictionary<string, TplSrc> ParseTpls(string json)
        {
            var res = new Dictionary<string, TplSrc>();
            foreach (var kv in MiniJson.O(MiniJson.Parse(json)))
            {
                var o = MiniJson.O(kv.Value);
                var t = new TplSrc();
                var s = Ints(o["s"]); t.sx = s[0]; t.sy = s[1]; t.sz = s[2];
                var p = MiniJson.L(o["p"]);
                t.pKey = new string[p.Count]; t.pMeta = new int[p.Count]; t.pWet = new int[p.Count];
                for (int i = 0; i < p.Count; i++)
                {
                    var e = MiniJson.L(p[i]);
                    t.pKey[i] = (string)e[0]; t.pMeta[i] = MiniJson.I(e[1]); t.pWet[i] = e.Count > 2 ? MiniJson.I(e[2]) : 0;
                }
                var m = MiniJson.L(o["m"]);
                t.m = new int[m.Count][];
                for (int i = 0; i < m.Count; i++) t.m[i] = Ints(m[i]);
                t.g = (string)o["g"];
                if (o.TryGetValue("d", out var dv))
                {
                    var dl = MiniJson.L(dv);
                    t.d = new (int, int, int, string)[dl.Count];
                    for (int i = 0; i < dl.Count; i++) { var e = MiniJson.L(dl[i]); t.d[i] = (MiniJson.I(e[0]), MiniJson.I(e[1]), MiniJson.I(e[2]), (string)e[3]); }
                }
                if (o.TryGetValue("j", out var jv))
                {
                    var jl = MiniJson.L(jv);
                    t.j = new int[jl.Count][];
                    for (int i = 0; i < jl.Count; i++) t.j[i] = Ints(jl[i]);
                }
                if (o.TryGetValue("r", out var rv))
                {
                    foreach (var rk in MiniJson.O(rv))
                    {
                        var states = new Dictionary<string, double[][]>();
                        if (rk.Value is Dictionary<string, object> so)
                        {
                            foreach (var sk in so)
                            {
                                if (sk.Key == "rot") { t.rRot[rk.Key] = MiniJson.D(sk.Value); continue; }
                                var rl = MiniJson.L(sk.Value);
                                var arr = new double[rl.Count][];
                                for (int i = 0; i < rl.Count; i++)
                                {
                                    var e = MiniJson.L(rl[i]);
                                    arr[i] = new double[e.Count];
                                    for (int q = 0; q < e.Count; q++) arr[i][q] = MiniJson.D(e[q]);
                                }
                                states[sk.Key] = arr;
                            }
                        }
                        t.r[rk.Key] = states;
                    }
                }
                if (o.TryGetValue("l", out var lv))
                {
                    var ll = MiniJson.L(lv);
                    t.l = new (int, int, int, string)[ll.Count];
                    for (int i = 0; i < ll.Count; i++) { var e = MiniJson.L(ll[i]); t.l[i] = (MiniJson.I(e[0]), MiniJson.I(e[1]), MiniJson.I(e[2]), (string)e[3]); }
                }
                res[kv.Key] = t;
            }
            return res;
        }
    }
}
